    "id": "mealdb-52838",
    "title": "Venetian Duck Ragu",
    "subtitle": "Italian · Pasta",
    "emoji": "🍝",
    "image": "https://www.themealdb.com/images/media/meals/qvrwpt1511181864.jpg",
