    "id": "mealdb-52878",
    "title": "Beef and Oyster pie",
    "subtitle": "British · Beef",
    "emoji": "🥩",
    "image": "https://www.themealdb.com/images/media/meals/wrssvt1511556563.jpg",
    "category": "dinner",
    "mealType": "dinner",
